 * This file was generated by the Gradle 'init' task.
 *
 * This generated file contains a sample Java application project to get you started.
 * For more details on building Java & JVM projects, please refer to https://docs.gradle.org/9.7.1/userguide/building_java_projects.html in the Gradle documentation.
 */

plugins {
    // Apply the application plugin to add support for building a CLI application in Java.
    application

    // Pulls in the platform-specific JavaFX modules and puts them on the module path.
    id("org.openjfx.javafxplugin") version "0.1.0"
}

repositories {
    // Use Maven Central for resolving dependencies.
    mavenCentral()
}

dependencies {
    // From the included build at ../java (see settings.gradle.kts).
    implementation("org.rapidcow.trivnote:libexpr")

    // Use JUnit Jupiter for testing.
    testImplementation(libs.junit.jupiter)

    testRuntimeOnly("org.junit.platform:junit-platform-launcher")
}

// Apply a specific Java toolchain to ease working on different environments.
java {
    toolchain {
        languageVersion = JavaLanguageVersion.of(25)
    }
}

javafx {
    version = "25"
    modules("javafx.controls", "javafx.fxml")
}

application {
    // Define the main class for the application.
    mainClass = "org.rapidcow.trivnote.desktop.MainApplication"

    // JavaFX loads its native libraries via System::load (JEP 472).
    applicationDefaultJvmArgs = listOf("--enable-native-access=javafx.graphics")
}

tasks.named<JavaExec>("run") {
    // The JavaFX plugin (0.1.0) sets up the module path in a doFirst action.
    notCompatibleWithConfigurationCache("org.openjfx.javafxplugin touches the project at execution time")
}

tasks.named<Test>("test") {
    // Use JUnit Platform for unit tests.
    useJUnitPlatform()
}
